$ErrorActionPreference = "Stop"
Set-Location $PSScriptRoot

Write-Host "============================================================"
Write-Host "GeoPilot Deterministic Terrain Engine V1"
Write-Host "DEM selection + elevation/slope summary + grounded tool wiring"
Write-Host "NO migration - NO frontend change - Track B protected"
Write-Host "============================================================"
Write-Host ""

docker compose config --services *> $null
if ($LASTEXITCODE -ne 0) { throw "Run from geopilot_v7 root and ensure Docker is running." }

Write-Host "[1/7] Applying controlled backend patch..."
$payload = ""
docker compose run --rm --no-deps -v "${PWD}:/workspace" -w /workspace backend python -c "import base64;exec(base64.b64decode('$payload'))"
if ($LASTEXITCODE -ne 0) { throw "Patch step failed" }

Write-Host ""
Write-Host "[2/7] Python compile gate..."
docker compose run --rm --no-deps -v "${PWD}:/workspace" -w /workspace/backend backend python -m compileall app/services/terrain_analysis.py app/services/planning_tools.py app/services/data_requirement_router.py app/services/planning_orchestrator.py tests/test_terrain_analysis.py tests/test_data_requirement_router.py
if ($LASTEXITCODE -ne 0) { throw "Compile gate failed" }

Write-Host ""
Write-Host "[3/7] Terrain Engine tests..."
docker compose run --rm --no-deps -v "${PWD}:/workspace" -w /workspace/backend -e PYTHONPATH=/workspace/backend backend pytest -q tests/test_terrain_analysis.py
if ($LASTEXITCODE -ne 0) { throw "Terrain tests failed" }

Write-Host ""
Write-Host "[4/7] Router regression tests..."
docker compose run --rm --no-deps -v "${PWD}:/workspace" -w /workspace/backend -e PYTHONPATH=/workspace/backend backend pytest -q tests/test_data_requirement_router.py
if ($LASTEXITCODE -ne 0) { throw "Router tests failed" }

Write-Host ""
Write-Host "[5/7] Existing Track B regression baseline..."
docker compose run --rm --no-deps -v "${PWD}:/workspace" -w /workspace/backend -e PYTHONPATH=/workspace/backend backend pytest -q tests/test_track_b_hackathon.py
if ($LASTEXITCODE -ne 0) { throw "Track B regression failed" }

Write-Host ""
Write-Host "[6/7] Recreating backend only..."
docker compose up -d --force-recreate backend
if ($LASTEXITCODE -ne 0) { throw "Backend recreate failed" }

Write-Host ""
Write-Host "[7/7] Runtime capability verification..."
Start-Sleep -Seconds 4
docker compose exec -T backend python -c "from app.services.data_requirement_router import route_question; from app.services.planning_tools import get_tool; r=route_question('berapa slope tertinggi di kawasan ini'); t=get_tool('terrain.site_summary'); print('ROUTE=',r.state,r.capability,list(r.tools)); print('REQUIRED_EVIDENCE=',list(r.required_evidence)); print('TOOL=',t); assert r.state=='planned'; assert r.tools==('terrain.site_summary',); assert t.deterministic and t.read_only"
if ($LASTEXITCODE -ne 0) { throw "Runtime verification failed" }

Write-Host ""
Write-Host "============================================================"
Write-Host "TERRAIN ENGINE V1 GATE PASS"
Write-Host "GeoPilot can now execute deterministic DEM elevation/slope analysis"
Write-Host "when exactly one strict project/site-scoped DEM is available."
Write-Host "If DEM is missing or ambiguous, the Planning Run fails closed."
Write-Host "Track B regression baseline remains green."
Write-Host "============================================================"
